        i0,i1,j0,j1=bb
        n=sum(1 for r in range(i0+1,i1) for q in range(j0+1,j1) if g[r][q]!=0)
        ih,iw=i1-i0-1,j1-j0-1
        cand=(n,(i1,bbox:=None)) or None
        # key: most interior nonzero cells among boxes whose interior is NOT empty? choose candidate with max n
        if best is None or n>best[0]:
            best=(n,bb,c)
    cnt,tpl_i,bg=best
    b0,b1,b2,b3=tpl_i
    pil=[[g[r][q]!=0 for q in range(b2+1,b3)] for r in range(b0+1,b1)]
    th,tw=b1-b0-1,b3-b2-1
    res=[row[:] for row in g]
    for bb,ps,c in ais:
        i0,i1,j0,j1=bb
        ih,iw=i1-i0-1,j1-j0-1
        if (ih,iw)!=(th,tw):
            for r in range(i0+1,i1):
                for q in range(j0+1,j1):
                    res[r][q]=0
            continue
        if bb==tpl_i: continue
        for r in range(i0+1,i1):
            for q in range(j0+1,j1):
                res[r][q]=c if pil[r-(i0+1)][q-(j0+1)] else 0
    return res
